/**
 * Analyzes PC specs & Primary Display against a game's requirements and computes:
 * 1. Can I Run It verdict (Cannot Run / Minimum / Recommended / Ultra Ready)
 * 2. Component pass/fail breakdown & bottleneck detection
 * 3. Screen-Aware Optimal Graphics Configurations across 4 modes:
 *    - `optimal`       : Smart Rig + Screen Optimal (Default)
 *    - `full_fps`      : Full FPS (Max Hz / Competitive)
 *    - `balanced`      : Balanced (FPS & Visual Quality)
 *    - `quality_30_60` : Quality (30–60 FPS Cinematic)
 */

const OPTIMIZATION_MODES = {
  optimal: {
    id: 'optimal',
    label: '🎯 Optimal (Rig + Screen)',
    shortLabel: 'Optimal'
  },
  full_fps: {
    id: 'full_fps',
    label: '🚀 Full FPS (Max Hz)',
    shortLabel: 'Full FPS'
  },
  balanced: {
    id: 'balanced',
    label: '⚖️ Balanced (FPS & Quality)',
    shortLabel: 'Balanced'
  },
  quality_30_60: {
    id: 'quality_30_60',
    label: '🎬 Quality (30–60 FPS)',
    shortLabel: 'Quality (30–60 FPS)'
  }
};

function normalizeOptimizationMode(mode = 'optimal') {
  const m = String(mode || 'optimal').toLowerCase().trim().replace(/-/g, '_');
  if (m === 'full_fps' || m === 'fullfps' || m === 'max_fps' || m === 'competitive') return 'full_fps';
  if (m === 'balanced' || m === 'balance') return 'balanced';
  if (m === 'quality_30_60' || m === 'quality' || m === 'cinematic' || m === '30_60') return 'quality_30_60';
  return 'optimal';
}

function evaluateComponent(userScore, minScore, recScore) {
  if (userScore >= recScore * 1.15) return 'EXCEEDS_RECOMMENDED';
  if (userScore >= recScore * 0.95) return 'MEETS_RECOMMENDED';
  if (userScore >= minScore * 0.95) return 'MEETS_MINIMUM';
  return 'BELOW_MINIMUM';
}

function resolveDisplaySpec(specs, targetDisplayOverride = null) {
  const raw = targetDisplayOverride || specs?.display || {};
  const width = Math.max(640, Number(raw.width) || 1920);
  const height = Math.max(480, Number(raw.height) || 1080);
  const refreshRateHz = Math.max(30, Math.round(Number(raw.refreshRateHz) || 60));
  const pixels = width * height;
  const tier = raw.tier || (height >= 2000 || width >= 3400 || pixels >= 6000000
    ? '4K'
    : (height >= 1350 || width >= 2400 || pixels >= 3000000 ? '1440p' : '1080p'));
  const name = raw.name || 'Primary Display';
  const deviceName = raw.deviceName || 'DISPLAY1';
  const aspectRatio = raw.aspectRatio || '16:9';
  const vrrCapable = raw.vrrCapable !== undefined ? Boolean(raw.vrrCapable) : refreshRateHz >= 75;

  return {
    name,
    deviceName,
    width,
    height,
    tier,
    refreshRateHz,
    aspectRatio,
    vrrCapable,
    resolutionLabel: `${width}x${height} (${tier})`
  };
}

function getResolutionFactorForPixels(width, height) {
  const basePixels = 1920 * 1080;
  const actualPixels = Math.max(1280 * 720, (Number(width) || 1920) * (Number(height) || 1080));
  const pixelRatio = actualPixels / basePixels;
  if (Math.abs(pixelRatio - 1) < 0.08) return 1.0;
  if (Math.abs(pixelRatio - (2560 * 1440) / basePixels) < 0.15) return 1.35;
  if (pixelRatio >= 3.5) return 2.05;
  return Number(Math.pow(pixelRatio, 0.58).toFixed(2));
}

function estimateFpsForResolution(specs, game, resolutionFactor, modeMultiplier = 1.0) {
  const baseTarget = Number(game.baseRecFps) || (game.id === 'counter-strike-2' ? 210 : game.id === 'forza-horizon-5' ? 95 : 64);
  const gpuRatio = specs.gpu.score / Math.max(15, game.recommended.gpuScore);
  const cpuRatio = specs.cpu.score / Math.max(15, game.recommended.cpuScore);

  const gpuWeight = resolutionFactor <= 1.05 ? 0.72 : resolutionFactor <= 1.45 ? 0.84 : 0.92;
  const cpuWeight = 1 - gpuWeight;

  const combinedRatio = (gpuRatio / resolutionFactor) * gpuWeight + cpuRatio * cpuWeight;

  const estVramNeeded = game.recommended.vramGB * (resolutionFactor <= 1.05 ? 0.9 : resolutionFactor <= 1.45 ? 1.15 : 1.45);
  const vramPenalty = specs.gpu.vramGB < estVramNeeded ? 0.78 : 1.0;

  const baseFps = Math.max(15, Math.round(baseTarget * combinedRatio * vramPenalty * modeMultiplier));
  const lowFps = Math.max(12, Math.round(baseFps * 0.85));
  const highFps = Math.max(18, Math.round(baseFps * 1.12));

  return {
    avg: baseFps,
    low: lowFps,
    high: highFps,
    range: `${lowFps} - ${highFps} FPS`
  };
}

function selectPreferredUpscaler(specs, game) {
  const upscalers = Array.isArray(game?.supportsUpscaling) && game.supportsUpscaling.length > 0
    ? game.supportsUpscaling
    : ['Native'];
  if (specs.gpu.vendor === 'nvidia' && upscalers.includes('DLSS')) return 'NVIDIA DLSS';
  if (upscalers.includes('FSR')) return 'AMD FSR';
  if (upscalers.includes('XeSS')) return 'Intel XeSS';
  return upscalers[0] || 'Native';
}

function buildModeProfile(modeKey, specs, game, overallTier, display) {
  const gpuRatio = specs.gpu.score / Math.max(15, game.recommended.gpuScore);
  const vramGB = specs.gpu.vramGB;
  const upscalerName = selectPreferredUpscaler(specs, game);
  const hasTemporalUpscaler = upscalerName !== 'Native';
  const supportsFG = /dlss\s*[34]|fsr\s*[34]/i.test(specs.gpu.upscaler || '') && vramGB >= 8;
  const screenResFactor = getResolutionFactorForPixels(display.width, display.height);
  const baselineScreenFps = estimateFpsForResolution(specs, game, screenResFactor, 1.0).avg;
  const vrrCapTarget = display.refreshRateHz >= 100 ? display.refreshRateHz - 4 : display.refreshRateHz;

  let preset = 'High';
  let targetResolution = `${display.width}x${display.height} (${display.tier} @ ${display.refreshRateHz}Hz)`;
  let upscalingMode = 'Off (Native)';
  let textures = vramGB >= 12 ? 'Ultra' : vramGB >= 8 ? 'High' : vramGB >= 6 ? 'Medium' : 'Low';
  let shadows = 'High';
  let rayTracing = 'Off';
  let frameGen = 'Off';
  let fpsMultiplier = 1.0;
  let qualityScore = 82;
  let targetFpsWindow = '60 - 120 FPS';
  let fpsCapAdvice = `Cap at ${vrrCapTarget} FPS with VRR (${specs.gpu.vendor === 'nvidia' ? 'G-Sync + Reflex' : 'FreeSync + Anti-Lag'})`;
  let summary = '';

  if (modeKey === 'full_fps') {
    // Mode 2: Full FPS (Max Hz / Competitive)
    preset = overallTier === 'EXCEEDS_RECOMMENDED' ? 'Medium / Competitive High' : 'Low / Competitive';
    upscalingMode = hasTemporalUpscaler
      ? (baselineScreenFps < display.refreshRateHz * 0.75 ? `${upscalerName} - Performance` : `${upscalerName} - Balanced`)
      : '85% Render Scale';
    textures = vramGB >= 8 ? 'High (Zero FPS Cost)' : vramGB >= 6 ? 'Medium' : 'Low';
    shadows = 'Low';
    rayTracing = 'Off (Disabled for Max FPS & Lowest Latency)';
    frameGen = supportsFG && display.refreshRateHz >= 120 && baselineScreenFps >= 55
      ? `On (Target ${display.refreshRateHz}Hz Saturation)`
      : 'Off (Lowest Input Latency)';
    fpsMultiplier = frameGen.startsWith('On') ? 1.52 : 1.34;
    qualityScore = 64;
    targetFpsWindow = `${Math.min(display.refreshRateHz, Math.max(90, display.refreshRateHz - 10))}+ FPS (Max ${display.refreshRateHz}Hz)`;
    fpsCapAdvice = display.refreshRateHz >= 120
      ? `Cap at ${display.refreshRateHz - 3} FPS + ${specs.gpu.vendor === 'nvidia' ? 'NVIDIA Reflex (+Boost)' : 'AMD Anti-Lag 2'} to saturate ${display.refreshRateHz}Hz VRR`
      : `Uncapped or ${display.refreshRateHz * 2} FPS cap for minimum frame delivery latency`;
    summary = `Tuned for maximum framerate and lowest input latency on ${display.name} (${display.width}x${display.height} @ ${display.refreshRateHz}Hz).`;
  } else if (modeKey === 'balanced') {
    // Mode 3: Balanced (FPS & Visual Quality)
    preset = overallTier === 'BELOW_MINIMUM' ? 'Low / Medium' : overallTier === 'MEETS_MINIMUM' ? 'Medium' : 'High';
    upscalingMode = hasTemporalUpscaler
      ? `${upscalerName} - Quality`
      : 'Off (Native 100%)';
    textures = vramGB >= 10 ? 'Ultra' : vramGB >= 8 ? 'High' : 'Medium';
    shadows = overallTier === 'BELOW_MINIMUM' ? 'Low' : 'Medium';
    rayTracing = 'Off (Rasterized High Lighting)';
    frameGen = supportsFG && display.refreshRateHz >= 120
      ? 'Optional (Enable for 100+ FPS smoothness)'
      : 'Off';
    fpsMultiplier = hasTemporalUpscaler ? 1.15 : 1.06;
    qualityScore = 82;
    targetFpsWindow = display.refreshRateHz >= 120 ? '75 - 120 FPS' : '60 - 75 FPS';
    fpsCapAdvice = `Lock at ${Math.min(vrrCapTarget, 120)} FPS with VRR enabled for consistent frame times`;
    summary = `Balanced sweet-spot between crisp High visuals and smooth ${targetFpsWindow} gameplay at ${display.width}x${display.height}.`;
  } else if (modeKey === 'quality_30_60') {
    // Mode 4: Quality (30-60 FPS Cinematic)
    if (overallTier === 'BELOW_MINIMUM') {
      preset = 'Medium (Cinematic Floor)';
      upscalingMode = hasTemporalUpscaler ? `${upscalerName} - Quality` : '90% Render Scale';
      shadows = 'Medium';
      rayTracing = 'Off';
      fpsMultiplier = 0.92;
      qualityScore = 76;
    } else if (overallTier === 'MEETS_MINIMUM') {
      preset = 'High';
      upscalingMode = hasTemporalUpscaler ? `${upscalerName} - Quality` : 'Off (Native 100%)';
      shadows = 'High';
      rayTracing = 'Off';
      fpsMultiplier = 0.88;
      qualityScore = 86;
    } else {
      preset = 'Ultra';
      const needsQualityUpscaleFor30 = baselineScreenFps * 0.78 < 38 && hasTemporalUpscaler;
      upscalingMode = needsQualityUpscaleFor30
        ? `${upscalerName} - Quality`
        : hasTemporalUpscaler
          ? `Off (Native ${display.tier}) / ${upscalerName} Native AA`
          : `Off (Native ${display.tier})`;
      textures = vramGB >= 10 ? 'Ultra' : 'High (Safe for 8GB VRAM)';
      shadows = 'Ultra';
      rayTracing = game.supportsRT && specs.gpu.rtCapable && vramGB >= 8 && baselineScreenFps >= 55
        ? (vramGB >= 12 ? 'High (Ray-Traced GI & Reflections)' : 'Medium (RT Reflections)')
        : 'Off';
      fpsMultiplier = rayTracing !== 'Off' ? 0.72 : (needsQualityUpscaleFor30 ? 0.9 : 0.82);
      qualityScore = rayTracing !== 'Off' ? 98 : 94;
    }
    frameGen = 'Off (Native Cinematic Frame Pacing)';
    targetFpsWindow = '30 - 60 FPS (Cinematic Fidelity)';
    fpsCapAdvice = baselineScreenFps * fpsMultiplier >= 58
      ? 'Lock at 60 FPS (16.6ms frame-time) for rock-steady cinematic presentation'
      : 'Lock at 40 FPS (on 120Hz+ VRR screen) or 30/45 FPS for zero frame-time judder';
    summary = `Maximizes Ultra/High visual fidelity at ${display.width}x${display.height} while maintaining a stable 30–60 FPS cinematic target.`;
  } else {
    // Mode 1: Optimal (Smart Rig + Screen Default)
    const isHighHzScreen = display.refreshRateHz >= 120;
    if (overallTier === 'BELOW_MINIMUM') {
      targetResolution = `${display.width}x${display.height} (or 1280x720)`;
      preset = 'Low';
      upscalingMode = hasTemporalUpscaler ? `${upscalerName} - Performance` : '75% Render Scale';
      textures = vramGB >= 6 ? 'Medium' : 'Low';
      shadows = 'Low';
      fpsMultiplier = 1.25;
      qualityScore = 60;
    } else if (overallTier === 'MEETS_MINIMUM') {
      preset = 'Medium';
      upscalingMode = hasTemporalUpscaler ? `${upscalerName} - Quality` : 'Off (Native)';
      textures = vramGB >= 8 ? 'High' : 'Medium';
      shadows = 'Medium';
      fpsMultiplier = 1.12;
      qualityScore = 75;
    } else if (overallTier === 'MEETS_RECOMMENDED') {
      preset = 'High';
      upscalingMode = (gpuRatio >= 1.15 && !isHighHzScreen) || !hasTemporalUpscaler
        ? 'Off (Native 100%)'
        : `${upscalerName} - Quality`;
      textures = vramGB >= 8 ? 'High' : 'Medium';
      shadows = isHighHzScreen && baselineScreenFps < 90 ? 'Medium / High' : 'High';
      if (supportsFG && isHighHzScreen) {
        frameGen = `Optional (Enable for ${display.refreshRateHz}Hz monitor)`;
      }
      fpsMultiplier = upscalingMode.includes('Quality') ? 1.12 : 1.0;
      qualityScore = 85;
    } else {
      // EXCEEDS_RECOMMENDED
      if (gpuRatio >= 1.45 && vramGB >= 12) {
        preset = 'Ultra';
        upscalingMode = hasTemporalUpscaler && (isHighHzScreen || display.tier !== '1080p')
          ? `${upscalerName} - Quality`
          : 'Off (Native)';
        textures = 'Ultra';
        shadows = 'High / Ultra';
        rayTracing = game.supportsRT && specs.gpu.rtCapable && !isHighHzScreen ? 'Medium / High' : 'Off';
        fpsMultiplier = 1.05;
        qualityScore = 93;
      } else {
        preset = 'High / Ultra Custom';
        upscalingMode = gpuRatio >= 1.25 && !isHighHzScreen
          ? 'Off (Native) at 1080p / Quality at 1440p'
          : `${upscalerName} - Quality`;
        textures = vramGB >= 10 ? 'Ultra' : 'High (Safe for 8GB VRAM)';
        shadows = 'High';
        rayTracing = game.supportsRT && specs.gpu.rtCapable && gpuRatio >= 1.5 && !isHighHzScreen
          ? 'Low / Medium'
          : 'Off (Recommended for max FPS)';
        if (supportsFG && isHighHzScreen) {
          frameGen = `On (for 100-${display.refreshRateHz} FPS smoothness)`;
          fpsMultiplier = 1.22;
        } else {
          fpsMultiplier = 1.08;
        }
        qualityScore = 88;
      }
    }
    targetFpsWindow = isHighHzScreen ? `80 - ${display.refreshRateHz} FPS` : '60+ FPS';
    fpsCapAdvice = isHighHzScreen
      ? `Enable VRR (FreeSync/G-Sync) + cap at ${vrrCapTarget} FPS on ${display.name} (${display.refreshRateHz}Hz)`
      : `Lock at ${display.refreshRateHz} FPS or enable VRR for tear-free pacing`;
    summary = `Auto-tuned for ${specs.gpu.name} (${vramGB}GB) paired with your ${display.name} (${display.width}x${display.height} @ ${display.refreshRateHz}Hz).`;
  }

  let estimatedScreenFps = estimateFpsForResolution(specs, game, screenResFactor, fpsMultiplier);
  if (modeKey === 'quality_30_60' && estimatedScreenFps.avg > 60) {
    // In Quality 30-60 mode, note that native rendering easily hits the 60 FPS ceiling
    fpsCapAdvice = `Lock at 60 FPS (rig achieves ~${estimatedScreenFps.avg} FPS uncapped at ${display.tier} Ultra)`;
  }

  const refreshSaturationPct = Math.min(100, Math.max(10, Math.round((estimatedScreenFps.avg / display.refreshRateHz) * 100)));

  return {
    mode: modeKey,
    label: OPTIMIZATION_MODES[modeKey].label,
    shortLabel: OPTIMIZATION_MODES[modeKey].shortLabel,
    targetResolution,
    preset,
    upscalingMode,
    textures,
    shadows,
    rayTracing,
    frameGen,
    fpsCapAdvice,
    targetFpsWindow,
    estimatedScreenFps,
    refreshSaturationPct,
    qualityScore,
    fpsMultiplier,
    summary
  };
}

function buildOptimalSettings(specs, game, overallTier, options = {}) {
  const activeMode = normalizeOptimizationMode(options.optimizationMode);
  const display = resolveDisplaySpec(specs, options.targetDisplay);

  const modeProfiles = {
    optimal: buildModeProfile('optimal', specs, game, overallTier, display),
    full_fps: buildModeProfile('full_fps', specs, game, overallTier, display),
    balanced: buildModeProfile('balanced', specs, game, overallTier, display),
    quality_30_60: buildModeProfile('quality_30_60', specs, game, overallTier, display)
  };

  const selected = modeProfiles[activeMode] || modeProfiles.optimal;
  const mult = selected.fpsMultiplier || 1.0;

  const fps1080p = estimateFpsForResolution(specs, game, 1.0, mult);
  const fps1440p = estimateFpsForResolution(specs, game, 1.35, mult);
  const fps4k = estimateFpsForResolution(specs, game, 2.05, mult);

  const displayTarget = {
    monitorName: display.name,
    deviceName: display.deviceName,
    width: display.width,
    height: display.height,
    tier: display.tier,
    aspectRatio: display.aspectRatio,
    resolutionLabel: display.resolutionLabel,
    refreshRateHz: display.refreshRateHz,
    vrrCapable: display.vrrCapable,
    targetFpsWindow: selected.targetFpsWindow,
    estimatedScreenFps: selected.estimatedScreenFps,
    refreshSaturationPct: selected.refreshSaturationPct,
    fpsCapAdvice: selected.fpsCapAdvice,
    syncAdvice: display.refreshRateHz >= 100
      ? `Enable FreeSync / G-Sync VRR + ${specs.gpu.vendor === 'nvidia' ? 'NVIDIA Reflex' : 'AMD Anti-Lag 2'} and cap FPS at ${display.refreshRateHz - 4} FPS.`
      : `Use VRR or a ${display.refreshRateHz} FPS cap for tear-free frame pacing.`
  };

  return {
    activeMode,
    activeModeLabel: selected.label,
    targetResolution: selected.targetResolution,
    preset: selected.preset,
    upscalingMode: selected.upscalingMode,
    textures: selected.textures,
    shadows: selected.shadows,
    rayTracing: selected.rayTracing,
    frameGen: selected.frameGen,
    fpsCapAdvice: selected.fpsCapAdvice,
    qualityScore: selected.qualityScore,
    summary: selected.summary,
    displayTarget,
    modeProfiles,
    estimatedFps: {
      '1080p': fps1080p,
      '1440p': fps1440p,
      '4K': fps4k
    },
    tuningTips: game.tuningTips || []
  };
}

function analyzeGameCompatibility(specs, game, options = {}) {
  const cpuStatus = evaluateComponent(specs.cpu.score, game.minimum.cpuScore, game.recommended.cpuScore);
  const gpuStatus = evaluateComponent(specs.gpu.score, game.minimum.gpuScore, game.recommended.gpuScore);
  const ramStatus = evaluateComponent(specs.ram.totalGB, game.minimum.ramGB, game.recommended.ramGB);
  const vramStatus = evaluateComponent(specs.gpu.vramGB, game.minimum.vramGB, game.recommended.vramGB);
  const storagePass = specs.storage.freeGB >= game.storageGB;

  const rankOrder = ['BELOW_MINIMUM', 'MEETS_MINIMUM', 'MEETS_RECOMMENDED', 'EXCEEDS_RECOMMENDED'];
  const minRankIndex = Math.min(
    rankOrder.indexOf(cpuStatus),
    rankOrder.indexOf(gpuStatus),
    rankOrder.indexOf(ramStatus),
    rankOrder.indexOf(vramStatus)
  );
  const overallTier = rankOrder[minRankIndex];

  const ratios = [
    { component: 'GPU Compute', ratio: specs.gpu.score / game.recommended.gpuScore, detail: specs.gpu.name },
    { component: 'GPU VRAM', ratio: specs.gpu.vramGB / game.recommended.vramGB, detail: `${specs.gpu.vramGB} GB VRAM` },
    { component: 'CPU', ratio: specs.cpu.score / game.recommended.cpuScore, detail: specs.cpu.name },
    { component: 'System RAM', ratio: specs.ram.totalGB / game.recommended.ramGB, detail: `${specs.ram.totalGB} GB RAM` }
  ].sort((a, b) => a.ratio - b.ratio);

  const limitingFactor = ratios[0];
  let bottleneckNote = '';
  if (limitingFactor.ratio < 1.0) {
    bottleneckNote = `Your ${limitingFactor.component} (${limitingFactor.detail}) is the primary limiting factor against Recommended specs.`;
  } else {
    bottleneckNote = `All components meet or exceed Recommended specs! At higher resolutions/settings, ${limitingFactor.component} (${limitingFactor.detail}) will be the first component fully utilized.`;
  }

  const optimalConfig = buildOptimalSettings(specs, game, overallTier, options);

  return {
    gameId: game.id,
    gameTitle: game.title,
    overallTier,
    canRunMinimum: minRankIndex >= 1,
    canRunRecommended: minRankIndex >= 2,
    storagePass,
    bottleneck: {
      limitingComponent: limitingFactor.component,
      note: bottleneckNote
    },
    components: {
      cpu: {
        status: cpuStatus,
        userValue: `${specs.cpu.name} (${specs.cpu.threads} threads)`,
        userScore: specs.cpu.score,
        minRequired: game.minimum.cpu,
        minScore: game.minimum.cpuScore,
        recRequired: game.recommended.cpu,
        recScore: game.recommended.cpuScore
      },
      gpu: {
        status: gpuStatus,
        userValue: `${specs.gpu.name} (${specs.gpu.vramGB} GB)`,
        userScore: specs.gpu.score,
        minRequired: game.minimum.gpu,
        minScore: game.minimum.gpuScore,
        recRequired: game.recommended.gpu,
        recScore: game.recommended.gpuScore
      },
      vram: {
        status: vramStatus,
        userValue: `${specs.gpu.vramGB} GB`,
        minRequired: `${game.minimum.vramGB} GB`,
        recRequired: `${game.recommended.vramGB} GB`
      },
      ram: {
        status: ramStatus,
        userValue: `${specs.ram.totalGB} GB`,
        minRequired: `${game.minimum.ramGB} GB`,
        recRequired: `${game.recommended.ramGB} GB`
      },
      storage: {
        status: storagePass ? 'MEETS_RECOMMENDED' : 'BELOW_MINIMUM',
        userValue: `${specs.storage.freeGB} GB Free (${specs.storage.drive})`,
        required: `${game.storageGB} GB (${game.ssdRequired ? 'SSD Required' : 'HDD/SSD'})`
      }
    },
    optimalConfig
  };
}

module.exports = {
  analyzeGameCompatibility,
  OPTIMIZATION_MODES,
  normalizeOptimizationMode,
  resolveDisplaySpec
};

const { detectSystemSpecs } = require('./hardware');
const { getAllGames } = require('./games-db');
const { analyzeGameCompatibility } = require('./analyzer');
const { scanInstalledGames } = require('./installed-scanner');
const { getPerSettingImpact } = require('./config-exporter');

function formatTierBadge(overallTier) {
  return overallTier === 'EXCEEDS_RECOMMENDED'
    ? '[ULTRA / HIGH READY]'
    : overallTier === 'MEETS_RECOMMENDED'
      ? '[RECOMMENDED READY]'
      : overallTier === 'MEETS_MINIMUM'
        ? '[MINIMUM READY]'
        : '[BELOW MINIMUM]';
}

function runCli() {
  const specs = detectSystemSpecs();
  const games = getAllGames();
  const installedGames = scanInstalledGames();

  console.log('==============================================================');
  console.log('   PC HARDWARE & GAME CONFIGURATION CHECKER (CLI)');
  console.log('==============================================================');
  console.log(`OS        : ${specs.os}`);
  console.log(`CPU       : ${specs.cpu.name} (${specs.cpu.cores}C/${specs.cpu.threads}T @ ${specs.cpu.speedGHz} GHz) [Score: ${specs.cpu.score}/100]`);
  console.log(`GPU       : ${specs.gpu.name} (${specs.gpu.vramGB} GB VRAM, Driver ${specs.gpu.driverVersion}) [Score: ${specs.gpu.score}/100]`);
  console.log(`RAM       : ${specs.ram.totalGB} GB Total (${specs.ram.freeGB} GB Free)`);
  console.log(`Disk      : ${specs.storage.freeGB} GB Free on ${specs.storage.drive} (${specs.storage.totalGB} GB Total)`);
  console.log(`Installed : ${installedGames.length} PC game(s) detected on local drives`);
  console.log('==============================================================\n');

  const rawArgs = process.argv.slice(2);
  const installedFlag = rawArgs.includes('--installed') || rawArgs.includes('-i');
  const query = rawArgs
    .filter((a) => a !== '--installed' && a !== '-i')
    .join(' ')
    .toLowerCase();

  if (installedFlag || (!query && installedGames.length > 0)) {
    console.log(`--- LOCALLY INSTALLED PC GAMES (${installedGames.length}) ---`);
    for (const inst of installedGames) {
      const res = analyzeGameCompatibility(specs, inst);
      console.log(`${formatTierBadge(res.overallTier)} ${inst.title} [${inst.launcher} • ${inst.drive} • ${inst.sizeOnDiskGB} GB]`);
      console.log(`  • Optimal Target : ${res.optimalConfig.targetResolution} @ ${res.optimalConfig.preset} Preset`);
      console.log(`  • Est. FPS       : 1080p: ${res.optimalConfig.estimatedFps['1080p'].range} | 1440p: ${res.optimalConfig.estimatedFps['1440p'].range}\n`);
    }
    if (installedFlag) return;
    console.log(`--- CATALOG GAMES (${games.length}) ---`);
  }

  let targetGames = query
    ? games.filter((g) => g.title.toLowerCase().includes(query) || g.id.includes(query))
    : games;

  if (query && targetGames.length === 0) {
    targetGames = installedGames.filter(
      (g) => g.title.toLowerCase().includes(query) || g.id.includes(query)
    );
  }

  for (const game of targetGames) {
    const res = analyzeGameCompatibility(specs, game);
    const badge = formatTierBadge(res.overallTier);

    console.log(`${badge} ${game.title} (${game.genre})`);
    console.log(`  • Optimal Target : ${res.optimalConfig.targetResolution} @ ${res.optimalConfig.preset} Preset`);
    console.log(`  • Upscaling      : ${res.optimalConfig.upscalingMode} | Frame Gen: ${res.optimalConfig.frameGen}`);
    console.log(`  • Est. FPS       : 1080p: ${res.optimalConfig.estimatedFps['1080p'].range} | 1440p: ${res.optimalConfig.estimatedFps['1440p'].range}`);
    console.log(`  • Bottleneck     : ${res.bottleneck.note}`);

    if (query) {
      const impacts = getPerSettingImpact(specs, game, res);
      console.log(`  • Per-Setting FPS Gain & VRAM Impact:`);
      for (const item of impacts) {
        console.log(
          `      - ${item.setting.padEnd(24)}: ${item.recommendedValue.padEnd(24)} (+${item.fpsGainPercent}% FPS | ~${item.vramImpactMB} MB VRAM | Visual Cost: ${item.visualCost})`
        );
      }
    }
    console.log('');
  }
}

runCli();

const { analyzeGameCompatibility, normalizeOptimizationMode } = require('./analyzer');

/**
 * Computes per-setting FPS gain (%) and VRAM impact (MB) tailored to the user's
 * detected GPU, VRAM, CPU, Display, and active Optimization Mode against the selected game.
 */
function getPerSettingImpact(specs, game, analysis, options = {}) {
  const resolvedAnalysis = analysis || analyzeGameCompatibility(specs, game, options);
  const baseOptimal = resolvedAnalysis.optimalConfig || {};
  const activeMode = options.optimizationMode
    ? normalizeOptimizationMode(options.optimizationMode)
    : (baseOptimal.activeMode || 'optimal');

  const optimal = (baseOptimal.modeProfiles && baseOptimal.modeProfiles[activeMode])
    ? { ...baseOptimal, ...baseOptimal.modeProfiles[activeMode], activeMode }
    : baseOptimal;

  const gpu = specs?.gpu || { name: 'Generic GPU', score: 45, vramGB: 6, vendor: 'unknown', rtCapable: false, upscaler: 'FSR' };
  const cpu = specs?.cpu || { name: 'Generic CPU', score: 50, cores: 6, threads: 12 };
  const display = baseOptimal.displayTarget || specs?.display || { monitorName: 'Primary Display', width: 1920, height: 1080, refreshRateHz: 60 };
  const recGpuScore = Math.max(15, game?.recommended?.gpuScore || 50);
  const recCpuScore = Math.max(15, game?.recommended?.cpuScore || 50);
  const recVramGB = Math.max(2, game?.recommended?.vramGB || 6);

  const gpuRatio = gpu.score / recGpuScore;
  const cpuRatio = cpu.score / recCpuScore;
  const vramHeadroomGB = gpu.vramGB - recVramGB;

  const supportsRT = Boolean(game?.supportsRT);
  const upscalers = Array.isArray(game?.supportsUpscaling) && game.supportsUpscaling.length > 0
    ? game.supportsUpscaling
    : ['Native'];
  const supportsUpscaling = !(upscalers.length === 1 && upscalers[0] === 'Native');
  const preferredUpscaler = gpu.vendor === 'nvidia' && upscalers.includes('DLSS')
    ? 'NVIDIA DLSS'
    : upscalers.includes('FSR')
      ? 'AMD FSR'
      : upscalers.includes('XeSS')
        ? 'Intel XeSS'
        : upscalers[0] || 'Native';

  const supportsFrameGen = /dlss\s*[34]|fsr\s*[34]/i.test(gpu.upscaler || '');

  // 1. Shadow Quality
  const shadowValue = optimal.shadows
    || (activeMode === 'full_fps'
      ? 'Low'
      : activeMode === 'quality_30_60'
        ? 'Ultra'
        : gpuRatio >= 1.3 ? 'High / Ultra' : gpuRatio >= 0.95 ? 'High' : 'Medium');
  const shadowFpsGain = activeMode === 'full_fps' ? 24 : gpuRatio < 0.85 ? 22 : gpuRatio < 1.15 ? 16 : 11;
  const shadowVramMB = shadowValue.includes('Low') ? 520 : shadowValue.includes('Medium') ? 380 : 240;

  // 2. Volumetric Fog / Clouds
  const fogValue = activeMode === 'full_fps'
    ? 'Low'
    : activeMode === 'quality_30_60'
      ? 'High / Ultra'
      : gpuRatio >= 1.35 ? 'High' : gpuRatio >= 0.9 ? 'Medium / High' : 'Low / Medium';
  const fogFpsGain = activeMode === 'full_fps' ? 21 : gpuRatio < 0.9 ? 19 : gpuRatio < 1.2 ? 15 : 10;
  const fogVramMB = 220;

  // 3. Ray Tracing
  let rtValue = optimal.rayTracing || 'Off';
  let rtFpsGain = 0;
  let rtVramMB = 0;
  let rtVisualCost = 'None';
  let rtNote = '';

  if (!supportsRT) {
    rtValue = 'Not Supported by Game';
    rtFpsGain = 0;
    rtVramMB = 0;
    rtVisualCost = 'None';
    rtNote = `${game.title} uses rasterized lighting only; no Ray Tracing overhead on ${gpu.name}.`;
  } else if (!gpu.rtCapable) {
    rtValue = 'Off (Hardware Unsupported)';
    rtFpsGain = 38;
    rtVramMB = 1250;
    rtVisualCost = 'Moderate';
    rtNote = `${gpu.name} lacks dedicated RT cores; keeping Ray Tracing Off avoids severe frame pacing stalls.`;
  } else if (activeMode === 'quality_30_60' && gpu.vramGB >= 8) {
    rtValue = optimal.rayTracing && optimal.rayTracing !== 'Off' ? optimal.rayTracing : 'Medium (Cinematic RT)';
    rtFpsGain = 22;
    rtVramMB = 1100;
    rtVisualCost = 'Low';
    rtNote = `Quality (30–60 FPS) mode enables ${rtValue} on ${gpu.name} for peak lighting fidelity.`;
  } else if (gpuRatio >= 1.45 && gpu.vramGB >= 12 && activeMode !== 'full_fps') {
    rtValue = 'Medium / High';
    rtFpsGain = 24;
    rtVramMB = 1100;
    rtVisualCost = 'Low-Medium';
    rtNote = `${gpu.name} (${gpu.vramGB} GB VRAM) has sufficient RT & VRAM headroom for hybrid Ray Tracing.`;
  } else {
    rtValue = activeMode === 'full_fps' ? 'Off (Disabled for Max Hz)' : 'Off (Recommended for FPS)';
    rtFpsGain = 34;
    rtVramMB = 1200;
    rtVisualCost = 'Moderate';
    rtNote = `Disabling RT on ${gpu.name} reclaims ~1.2 GB VRAM and boosts frame rate by ~${rtFpsGain}%.`;
  }

  // 4. Upscaling (FSR/DLSS)
  let upscalingValue = optimal.upscalingMode || 'Off (Native)';
  let upscalingFpsGain = 0;
  let upscalingVramMB = 0;
  let upscalingVisualCost = 'Minimal';
  let upscalingNote = '';

  if (!supportsUpscaling) {
    upscalingValue = activeMode === 'full_fps' ? '85% Render Scale' : 'Native (100% Scale)';
    upscalingFpsGain = activeMode === 'full_fps' || gpuRatio < 0.85 ? 18 : 0;
    upscalingVramMB = 180;
    upscalingVisualCost = 'Low';
    upscalingNote = `${game.title} does not include built-in temporal upscalers; use driver-level RSR/NIS if extra FPS is needed.`;
  } else {
    upscalingFpsGain = upscalingValue.includes('Performance')
      ? 38
      : upscalingValue.includes('Balanced')
        ? 29
        : gpuRatio < 0.85 ? 34 : 22;
    upscalingVramMB = 420;
    upscalingVisualCost = upscalingValue.includes('Performance') ? 'Low-Medium' : 'Minimal';
    upscalingNote = `${preferredUpscaler} (${upscalingValue}) reduces shader load at ${display.width}x${display.height} (${display.refreshRateHz}Hz).`;
  }

  // 5. Ambient Occlusion
  const aoValue = activeMode === 'full_fps'
    ? 'Low / Off'
    : activeMode === 'quality_30_60'
      ? 'HBAO+ / RTAO Ultra'
      : gpuRatio >= 1.1 ? 'HBAO+ / High' : gpuRatio >= 0.8 ? 'SSAO (Medium)' : 'Low / Off';
  const aoFpsGain = activeMode === 'full_fps' ? 12 : gpuRatio < 0.85 ? 10 : 7;
  const aoVramMB = 160;

  // 6. Texture Quality
  const textureValue = optimal.textures || (gpu.vramGB >= 12 ? 'Ultra' : gpu.vramGB >= 8 ? 'High' : gpu.vramGB >= 6 ? 'Medium' : 'Low');
  const textureFpsGain = vramHeadroomGB < 0 ? 18 : 3;
  const textureVramMB = gpu.vramGB >= 12 ? 1600 : gpu.vramGB >= 8 ? 1050 : 650;
  const textureVisualCost = vramHeadroomGB < 0 ? 'Moderate (Prevents Stutter)' : 'None (VRAM Bound)';
  const textureNote = vramHeadroomGB >= 0
    ? `Your ${gpu.vramGB} GB VRAM handles ${textureValue} textures without frame-time spikes (${recVramGB} GB recommended).`
    : `Lowering textures to ${textureValue} prevents PCIe VRAM spillover stutter on ${gpu.vramGB} GB VRAM (${recVramGB} GB recommended).`;

  // 7. Crowd / Foliage Density
  const crowdValue = activeMode === 'full_fps'
    ? (cpuRatio >= 1.2 ? 'Medium' : 'Low')
    : activeMode === 'quality_30_60'
      ? 'High / Ultra'
      : cpuRatio >= 1.15 ? 'High' : cpuRatio >= 0.9 ? 'Medium' : 'Low';
  const crowdFpsGain = activeMode === 'full_fps' ? 18 : cpuRatio < 0.95 ? 16 : 11;
  const crowdVramMB = 210;
  const crowdVisualCost = crowdValue === 'Low' ? 'Moderate' : 'Low';
  const crowdNote = cpuRatio < 1.0 || activeMode === 'full_fps'
    ? `Tuned to ${crowdValue} for ${cpu.name} (${cpu.threads} threads) to prevent 1% low drops and maximize ${display.refreshRateHz}Hz pacing.`
    : `${cpu.name} (${cpu.threads} threads) comfortably sustains ${crowdValue} simulation & draw-call density.`;

  // 8. Frame Generation
  let fgValue = optimal.frameGen || 'Off';
  let fgFpsGain = 0;
  let fgVramMB = 0;
  let fgVisualCost = 'Minimal';
  let fgNote = '';

  if (activeMode === 'quality_30_60') {
    fgValue = 'Off (Native 30–60 FPS Pacing)';
    fgFpsGain = 0;
    fgVramMB = 350;
    fgVisualCost = 'None';
    fgNote = 'Disabled in Quality (30–60 FPS) mode to avoid interpolation artifacts at lower base framerates.';
  } else if (supportsFrameGen && gpu.vramGB >= 8) {
    fgValue = optimal.frameGen && optimal.frameGen !== 'Off'
      ? optimal.frameGen
      : (gpuRatio >= 0.95 ? 'On (DLSS 3 / FSR 3 FG)' : 'Optional (Requires 55+ Base FPS)');
    fgFpsGain = 42;
    fgVramMB = 380;
    fgVisualCost = 'Minimal';
    fgNote = `${gpu.name} supports ${gpu.upscaler} Frame Generation; ideal for saturating ${display.refreshRateHz}Hz displays with Reflex/Anti-Lag.`;
  } else {
    fgValue = 'Off';
    fgFpsGain = 0;
    fgVramMB = 350;
    fgVisualCost = 'None';
    fgNote = gpu.vramGB < 8
      ? `Kept Off on ${gpu.vramGB} GB VRAM to reserve memory buffer for textures and frame pacing.`
      : `Use standard VRR / G-Sync / FreeSync pacing on ${gpu.name} for lowest input latency.`;
  }

  return [
    {
      setting: 'Shadow Quality',
      recommendedValue: shadowValue,
      fpsGainPercent: shadowFpsGain,
      vramImpactMB: shadowVramMB,
      visualCost: 'Low',
      note: `Dropping Cascade Shadows from Ultra to ${shadowValue} saves ~${shadowFpsGain}% GPU time on ${gpu.name}.`
    },
    {
      setting: 'Volumetric Fog / Clouds',
      recommendedValue: fogValue,
      fpsGainPercent: fogFpsGain,
      vramImpactMB: fogVramMB,
      visualCost: 'Minimal',
      note: `Volumetric ray-marching is heavy on pixel shaders; ${fogValue} preserves atmosphere while gaining +${fogFpsGain}% FPS.`
    },
    {
      setting: 'Ray Tracing',
      recommendedValue: rtValue,
      fpsGainPercent: rtFpsGain,
      vramImpactMB: rtVramMB,
      visualCost: rtVisualCost,
      note: rtNote
    },
    {
      setting: 'Upscaling (FSR/DLSS)',
      recommendedValue: upscalingValue,
      fpsGainPercent: upscalingFpsGain,
      vramImpactMB: upscalingVramMB,
      visualCost: upscalingVisualCost,
      note: upscalingNote
    },
    {
      setting: 'Ambient Occlusion',
      recommendedValue: aoValue,
      fpsGainPercent: aoFpsGain,
      vramImpactMB: aoVramMB,
      visualCost: 'Low',
      note: `${aoValue} balances contact shading depth and post-process cost (+${aoFpsGain}% FPS vs Ultra).`
    },
    {
      setting: 'Texture Quality',
      recommendedValue: textureValue,
      fpsGainPercent: textureFpsGain,
      vramImpactMB: textureVramMB,
      visualCost: textureVisualCost,
      note: textureNote
    },
    {
      setting: 'Crowd / Foliage Density',
      recommendedValue: crowdValue,
      fpsGainPercent: crowdFpsGain,
      vramImpactMB: crowdVramMB,
      visualCost: crowdVisualCost,
      note: crowdNote
    },
    {
      setting: 'Frame Generation',
      recommendedValue: fgValue,
      fpsGainPercent: fgFpsGain,
      vramImpactMB: fgVramMB,
      visualCost: fgVisualCost,
      note: fgNote
    }
  ];
}

function toQualityIndex(label = '') {
  const s = String(label).toLowerCase();
  if (s.includes('ultra')) return 3;
  if (s.includes('high')) return 2;
  if (s.includes('medium')) return 1;
  return 0;
}

function slugifyGame(game) {
  const raw = game?.id || game?.title || 'pc-game';
  return String(raw)
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '') || 'pc-game';
}

/**
 * Generates downloadable configuration files (.ini, .json, .md) for a game, PC hardware profile,
 * active screen, and selected optimization mode.
 */
function exportGameConfigFiles(specs, game, analysis, options = {}) {
  const resolvedAnalysis = analysis || analyzeGameCompatibility(specs, game, options);
  const perSettingImpact = getPerSettingImpact(specs, game, resolvedAnalysis, options);
  const baseOptimal = resolvedAnalysis.optimalConfig || {};
  const activeMode = options.optimizationMode
    ? normalizeOptimizationMode(options.optimizationMode)
    : (baseOptimal.activeMode || 'optimal');
  const optimal = (baseOptimal.modeProfiles && baseOptimal.modeProfiles[activeMode])
    ? { ...baseOptimal, ...baseOptimal.modeProfiles[activeMode], activeMode }
    : baseOptimal;

  const displayTarget = optimal.displayTarget || specs?.display || {
    monitorName: 'Primary Display',
    width: 1920,
    height: 1080,
    refreshRateHz: 60,
    resolutionLabel: '1920x1080 (1080p)'
  };

  const slug = slugifyGame(game);
  const filenameBase = `${slug}-${activeMode.replace(/_/g, '-')}-settings`;

  const settingMap = {};
  for (const item of perSettingImpact) {
    settingMap[item.setting] = item;
  }

  const shadowIdx = toQualityIndex(settingMap['Shadow Quality']?.recommendedValue);
  const fogIdx = toQualityIndex(settingMap['Volumetric Fog / Clouds']?.recommendedValue);
  const texIdx = toQualityIndex(settingMap['Texture Quality']?.recommendedValue);
  const aoIdx = toQualityIndex(settingMap['Ambient Occlusion']?.recommendedValue);
  const crowdIdx = toQualityIndex(settingMap['Crowd / Foliage Density']?.recommendedValue);
  const rtEnabled = /medium|high|on|ultra/i.test(settingMap['Ray Tracing']?.recommendedValue || '') &&
    !/off|not|unsupported/i.test(settingMap['Ray Tracing']?.recommendedValue || '');
  const fgEnabled = /^on/i.test(settingMap['Frame Generation']?.recommendedValue || '');

  const resolutionMatch = (optimal.targetResolution || `${displayTarget.width}x${displayTarget.height}`).match(/(\d{3,5})x(\d{3,5})/);
  const resX = resolutionMatch ? Number(resolutionMatch[1]) : (displayTarget.width || 1920);
  const resY = resolutionMatch ? Number(resolutionMatch[2]) : (displayTarget.height || 1080);
  const hz = displayTarget.refreshRateHz || 60;

  const iniLines = [
    `; ============================================================================`,
    `; PC Game Compatibility & Screen-Aware Optimal Graphics Profile (.INI)`,
    `; Game: ${game.title} (${game.engine || 'Custom Engine'})`,
    `; Optimization Mode: ${optimal.label || activeMode.toUpperCase()}`,
    `; Generated For: ${specs.cpu.name} | ${specs.gpu.name} (${specs.gpu.vramGB} GB VRAM) | ${specs.ram.totalGB} GB RAM`,
    `; Target Display: ${displayTarget.monitorName || displayTarget.name} (${resX}x${resY} @ ${hz}Hz)`,
    `; Compatibility Verdict: ${resolvedAnalysis.overallTier}`,
    `; Estimated Screen FPS: ${optimal.estimatedScreenFps?.range || optimal.estimatedFps?.['1080p']?.range || '60 FPS'}`,
    `; ============================================================================`,
    ``,
    `[Display]`,
    `FullscreenMode=WindowedFullscreen`,
    `ResolutionSizeX=${resX}`,
    `ResolutionSizeY=${resY}`,
    `RefreshRateHz=${hz}`,
    `MonitorModel="${displayTarget.monitorName || displayTarget.name || 'Primary Display'}"`,
    `TargetResolution="${optimal.targetResolution || '1920x1080 (1080p)'}"`,
    `OptimizationMode="${activeMode}"`,
    `OverallPreset="${optimal.preset || 'High'}"`,
    `FrameRateCapAdvice="${optimal.fpsCapAdvice || ''}"`,
    `VSync=False`,
    `VariableRefreshRate=${hz >= 75 ? 'True' : 'False'}`,
    ``,
    `[Graphics.OptimalSettings]`,
    `ShadowQuality="${settingMap['Shadow Quality']?.recommendedValue}"`,
    `VolumetricFogClouds="${settingMap['Volumetric Fog / Clouds']?.recommendedValue}"`,
    `RayTracing="${settingMap['Ray Tracing']?.recommendedValue}"`,
    `UpscalingMode="${settingMap['Upscaling (FSR/DLSS)']?.recommendedValue}"`,
    `AmbientOcclusion="${settingMap['Ambient Occlusion']?.recommendedValue}"`,
    `TextureQuality="${settingMap['Texture Quality']?.recommendedValue}"`,
    `CrowdFoliageDensity="${settingMap['Crowd / Foliage Density']?.recommendedValue}"`,
    `FrameGeneration="${settingMap['Frame Generation']?.recommendedValue}"`,
    ``,
    `[ScalabilityGroups]`,
    `sg.ResolutionQuality=${/performance/i.test(optimal.upscalingMode || '') ? 58 : /balanced/i.test(optimal.upscalingMode || '') ? 62 : /quality/i.test(optimal.upscalingMode || '') ? 67 : 100}`,
    `sg.ViewDistanceQuality=${Math.max(1, crowdIdx)}`,
    `sg.AntiAliasingQuality=2`,
    `sg.ShadowQuality=${shadowIdx}`,
    `sg.GlobalIlluminationQuality=${rtEnabled ? 3 : Math.max(1, fogIdx)}`,
    `sg.ReflectionQuality=${rtEnabled ? 3 : Math.max(1, shadowIdx)}`,
    `sg.PostProcessQuality=${aoIdx}`,
    `sg.TextureQuality=${texIdx}`,
    `sg.EffectsQuality=${fogIdx}`,
    `sg.FoliageQuality=${crowdIdx}`,
    `sg.ShadingQuality=2`,
    ``,
    `[RayTracing]`,
    `r.RayTracing=${rtEnabled ? 1 : 0}`,
    `r.RayTracing.Shadows=${rtEnabled ? 1 : 0}`,
    `r.RayTracing.Reflections=${rtEnabled ? 1 : 0}`,
    `r.FrameGeneration.Enabled=${fgEnabled ? 1 : 0}`,
    `r.Streaming.PoolSize=${Math.max(2048, Math.round(specs.gpu.vramGB * 1024 * 0.72))}`
  ];

  const iniContent = iniLines.join('\n') + '\n';

  const jsonPayload = {
    schemaVersion: '2.0',
    generatedAt: new Date().toISOString(),
    optimizationMode: activeMode,
    optimizationModeLabel: optimal.label || activeMode,
    game: {
      id: game.id,
      title: game.title,
      genre: game.genre || 'PC Game',
      engine: game.engine || 'Standard',
      storageGB: game.storageGB,
      ssdRequired: Boolean(game.ssdRequired)
    },
    hardwareProfile: {
      os: specs.os,
      cpu: {
        name: specs.cpu.name,
        cores: specs.cpu.cores,
        threads: specs.cpu.threads,
        score: specs.cpu.score
      },
      gpu: {
        name: specs.gpu.name,
        vramGB: specs.gpu.vramGB,
        vendor: specs.gpu.vendor,
        rtCapable: specs.gpu.rtCapable,
        upscaler: specs.gpu.upscaler,
        score: specs.gpu.score
      },
      ramGB: specs.ram.totalGB,
      display: displayTarget
    },
    compatibility: {
      overallTier: resolvedAnalysis.overallTier,
      canRunMinimum: resolvedAnalysis.canRunMinimum,
      canRunRecommended: resolvedAnalysis.canRunRecommended,
      storagePass: resolvedAnalysis.storagePass,
      bottleneck: resolvedAnalysis.bottleneck
    },
    optimalConfig: optimal,
    perSettingImpact
  };

  const jsonContent = JSON.stringify(jsonPayload, null, 2);

  const tipsSection = (optimal.tuningTips && optimal.tuningTips.length > 0)
    ? optimal.tuningTips.map((t) => `- ${t}`).join('\n')
    : `- Keep GPU drivers updated and enable Resizable BAR / Smart Access Memory in BIOS.`;

  const settingsTableRows = perSettingImpact
    .map(
      (s) =>
        `| **${s.setting}** | \`${s.recommendedValue}\` | +${s.fpsGainPercent}% FPS | ~${s.vramImpactMB} MB | ${s.visualCost} | ${s.note} |`
    )
    .join('\n');

  const markdownGuide = [
    `# ${game.title} — Optimal PC Settings & Tuning Checklist`,
    ``,
    `> **Verdict**: \`${resolvedAnalysis.overallTier}\` • **Mode**: \`${optimal.label || activeMode}\`  `,
    `> **Hardware Profile**: ${specs.cpu.name} (${specs.cpu.threads}T) • ${specs.gpu.name} (${specs.gpu.vramGB} GB VRAM) • ${specs.ram.totalGB} GB RAM  `,
    `> **Target Display**: ${displayTarget.monitorName || displayTarget.name} (${resX}x${resY} @ ${hz}Hz)`,
    ``,
    `## 1. Target Display, Mode & Estimated Performance`,
    `- **Optimization Mode**: **${optimal.label || activeMode}** — ${optimal.summary || ''}`,
    `- **Recommended Resolution**: **${optimal.targetResolution || '1920x1080 (1080p)'}**`,
    `- **Base Preset**: **${optimal.preset || 'High'}**`,
    `- **Screen FPS (${resX}x${resY} @ ${hz}Hz)**: **${optimal.estimatedScreenFps?.avg || optimal.estimatedFps?.['1080p']?.avg || 60} FPS avg** (${optimal.estimatedScreenFps?.range || '50 - 70 FPS'})`,
    `- **Frame Pacing / VRR Advice**: ${optimal.fpsCapAdvice || ''}`,
    `- **1080p Estimate**: ${optimal.estimatedFps?.['1080p']?.avg || 60} FPS avg (${optimal.estimatedFps?.['1080p']?.range || '50 - 70 FPS'})`,
    `- **1440p Estimate**: ${optimal.estimatedFps?.['1440p']?.avg || 45} FPS avg (${optimal.estimatedFps?.['1440p']?.range || '38 - 52 FPS'})`,
    `- **4K Estimate**: ${optimal.estimatedFps?.['4K']?.avg || 30} FPS avg (${optimal.estimatedFps?.['4K']?.range || '24 - 35 FPS'})`,
    ``,
    `## 2. Per-Setting FPS Gain & VRAM Impact Breakdown`,
    `| Setting | Recommended Value | Est. FPS Gain | VRAM Impact | Visual Cost | Hardware Note |`,
    `| :--- | :--- | :--- | :--- | :--- | :--- |`,
    settingsTableRows,
    ``,
    `## 3. Bottleneck & Hardware Notes`,
    `- **Primary Limiting Factor**: **${resolvedAnalysis.bottleneck?.limitingComponent || 'GPU'}**`,
    `- ${resolvedAnalysis.bottleneck?.note || ''}`,
    ``,
    `## 4. Game-Specific Optimization Checklist`,
    tipsSection,
    ``
  ].join('\n');

  return {
    iniContent,
    jsonContent,
    markdownGuide,
    filenameBase
  };
}

module.exports = {
  getPerSettingImpact,
  exportGameConfigFiles
};

/**
 * Native Windows Desktop App Launcher for RigCheck (PC Game Compatibility & Optimal Settings)
 *
 * 1. Starts the local Node.js backend (`src/server.js`) on port 3040 (or reuses it if already running).
 * 2. Waits until `http://localhost:3040/api/specs` responds Ready.
 * 3. Launches a standalone chromeless Windows desktop window using Microsoft Edge or Google Chrome
 *    in `--app` mode with an isolated `--user-data-dir` so window lifecycle is tracked accurately.
 * 4. Automatically shuts down the Node.js server when the user closes the desktop app window.
 */

const fs = require('fs');
const path = require('path');
const os = require('os');
const http = require('http');
const { spawn } = require('child_process');

const PORT = Number(process.env.PORT) || 3040;
const APP_URL = `http://localhost:${PORT}`;

function findDesktopBrowserBinary() {
  const localAppData = process.env.LOCALAPPDATA || '';
  const programFiles = process.env['ProgramFiles'] || 'C:\\Program Files';
  const programFilesX86 = process.env['ProgramFiles(x86)'] || 'C:\\Program Files (x86)';

  const candidates = [
    path.join(programFilesX86, 'Microsoft', 'Edge', 'Application', 'msedge.exe'),
    path.join(programFiles, 'Microsoft', 'Edge', 'Application', 'msedge.exe'),
    localAppData ? path.join(localAppData, 'Microsoft', 'Edge', 'Application', 'msedge.exe') : '',
    path.join(programFiles, 'Google', 'Chrome', 'Application', 'chrome.exe'),
    path.join(programFilesX86, 'Google', 'Chrome', 'Application', 'chrome.exe'),
    localAppData ? path.join(localAppData, 'Google', 'Chrome', 'Application', 'chrome.exe') : '',
    path.join(programFiles, 'BraveSoftware', 'Brave-Browser', 'Application', 'brave.exe'),
    localAppData ? path.join(localAppData, 'BraveSoftware', 'Brave-Browser', 'Application', 'brave.exe') : ''
  ].filter(Boolean);

  for (const binPath of candidates) {
    try {
      if (fs.existsSync(binPath)) {
        return binPath;
      }
    } catch (e) {
      // ignore inaccessible paths
    }
  }
  return null;
}

function probeServerReady(timeoutMs = 1200) {
  return new Promise((resolve) => {
    const req = http.get(`${APP_URL}/api/specs`, { timeout: timeoutMs }, (res) => {
      res.resume();
      resolve(res.statusCode === 200);
    });
    req.on('error', () => resolve(false));
    req.on('timeout', () => {
      req.destroy();
      resolve(false);
    });
  });
}

async function waitForServer(maxAttempts = 30, intervalMs = 250) {
  for (let i = 0; i < maxAttempts; i++) {
    const ready = await probeServerReady();
    if (ready) return true;
    await new Promise((r) => setTimeout(r, intervalMs));
  }
  return false;
}

async function launchDesktopApp() {
  const isCheckOnly = process.argv.includes('--check');
  const browserBin = findDesktopBrowserBinary();

  const alreadyRunning = await probeServerReady();
  if (!alreadyRunning) {
    require('./server');
  }

  const ready = await waitForServer();
  if (!ready) {
    console.error(`[RigCheck Desktop] Failed to reach backend at ${APP_URL}`);
    process.exit(1);
  }

  if (isCheckOnly) {
    console.log(JSON.stringify({
      status: 'READY',
      url: APP_URL,
      browserBin: browserBin || 'fallback-start',
      alreadyRunning
    }));
    process.exit(0);
  }

  const profileDir = path.join(os.tmpdir(), 'rigcheck-desktop-window-profile');
  try {
    fs.mkdirSync(profileDir, { recursive: true });
  } catch (e) {
    // ignore if exists
  }

  if (browserBin) {
    const args = [
      `--app=${APP_URL}`,
      '--window-size=1420,920',
      `--user-data-dir=${profileDir}`,
      '--no-first-run',
      '--no-default-browser-check',
      '--disable-features=Translate,msEdgeSidebarV2'
    ];

    console.log(`[RigCheck Desktop] Launching native window via: ${path.basename(browserBin)}`);
    const child = spawn(browserBin, args, {
      stdio: 'ignore',
      detached: false
    });

    child.on('exit', () => {
      console.log('[RigCheck Desktop] Window closed. Shutting down RigCheck server.');
      process.exit(0);
    });

    child.on('error', (err) => {
      console.error(`[RigCheck Desktop] Error launching window: ${err.message}`);
      process.exit(1);
    });
  } else {
    console.log(`[RigCheck Desktop] Opening ${APP_URL} in default browser...`);
    spawn('cmd.exe', ['/c', 'start', '', APP_URL], { stdio: 'ignore' });
  }
}

if (require.main === module) {
  launchDesktopApp();
}

module.exports = {
  findDesktopBrowserBinary,
  probeServerReady,
  launchDesktopApp
};

