const { scanInstalledGames } = require('./installed-scanner');
const { parseRawRequirementsText, filterAndSortGames } = require('./steam-lookup');
const { getPerSettingImpact, exportGameConfigFiles } = require('./config-exporter');
const {
  resolveSpecsWithOverrides,
  getPatchStatus,
  applyPatch,
  createPatch,
  rollbackPatch,
  getFirewallStatus,
  requestFirewallAccess,
  revokeFirewallAccess,
  searchComponentDeals
} = require('./ipc-handlers');

const PORT = process.env.PORT || 3040;
const PUBLIC_DIR = path.join(__dirname, '..', 'public');

let cachedSpecs = null;
let cachedInstalled = null;

function getSpecs(forceRefresh = false) {
  if (!cachedSpecs || forceRefresh) {
    cachedSpecs = detectSystemSpecs();
  }
  return cachedSpecs;
}

function getInstalled(forceRefresh = false) {
  if (!cachedInstalled || forceRefresh) {
    cachedInstalled = scanInstalledGames();
  }
  return cachedInstalled;
}

function sendJson(res, statusCode, payload) {
  res.writeHead(statusCode, { 'Content-Type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(payload, null, 2));
}

function parseBody(req) {
  return new Promise((resolve, reject) => {
    let body = '';
    req.on('data', (chunk) => {
      body += chunk.toString();
      if (body.length > 1e6) req.destroy();
    });
    req.on('end', () => {
      try {
        resolve(body ? JSON.parse(body) : {});
      } catch (e) {
        reject(e);
      }
    });
    req.on('error', reject);
  });
}

const MIME_TYPES = {
  '.html': 'text/html; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.js': 'application/javascript; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.svg': 'image/svg+xml'
};

const server = http.createServer(async (req, res) => {
  const parsedUrl = new URL(req.url, `http://${req.headers.host}`);
  const pathname = parsedUrl.pathname;

  // API: Get detected PC specs
  if (pathname === '/api/specs' && req.method === 'GET') {
    const refresh = parsedUrl.searchParams.get('refresh') === '1';
    if (refresh) getInstalled(true);
    return sendJson(res, 200, getSpecs(refresh));
  }

  // API: Get all catalog games + compatibility summary with current specs
  if (pathname === '/api/games' && req.method === 'GET') {
    const specs = getSpecs();
    const installedList = getInstalled();
    const optimizationMode = parsedUrl.searchParams.get('mode') || 'optimal';
    const installedByCatalogId = new Map();
    for (const inst of installedList) {
      if (inst.matchedCatalogId) {
        installedByCatalogId.set(inst.matchedCatalogId, inst);
      }
    }

    const rawGames = getAllGames().map((game) => {
      const inst = installedByCatalogId.get(game.id);
      return {
        ...game,
        steamAppId: (inst && inst.steamAppId) || game.steamAppId || null,
        bannerUrl: (inst && inst.bannerUrl) || game.bannerUrl,
        logoUrl: (inst && inst.logoUrl) || game.logoUrl,
        fallbackBannerSvg: (inst && inst.fallbackBannerSvg) || game.fallbackBannerSvg,
        fallbackLogoSvg: (inst && inst.fallbackLogoSvg) || game.fallbackLogoSvg,
        monogram: (inst && inst.monogram) || game.monogram,
        installed: Boolean(inst),
        launcher: inst ? inst.launcher : null,
        drive: inst ? inst.drive : null,
        sizeOnDiskGB: inst ? inst.sizeOnDiskGB : null,
        installDir: inst ? inst.installDir : null,
        runtime: inst && inst.runtime ? inst.runtime : null,
        protonVersion: inst && inst.protonVersion ? inst.protonVersion : null,
        linuxCompatNote: inst && inst.linuxCompatNote ? inst.linuxCompatNote : null,
        isRunning: Boolean(inst && inst.isRunning),
        wasRecentlyPlayed: Boolean(inst && inst.wasRecentlyPlayed),
        playStatus: inst ? inst.playStatus || 'INSTALLED' : 'CATALOG',
        playStatusLabel: inst ? inst.playStatusLabel || '💾 Installed' : '📚 Catalog',
        lastPlayedTimestamp: inst ? inst.lastPlayedTimestamp || 0 : 0,
        analysis: analyzeGameCompatibility(specs, game, {
          optimizationMode,
          targetDisplay: specs.display
        })
      };
    });

    const filteredGames = filterAndSortGames(rawGames, {
      query: parsedUrl.searchParams.get('q') || '',
      genre: parsedUrl.searchParams.get('genre') || '',
      tier: parsedUrl.searchParams.get('tier') || '',
      sortBy: parsedUrl.searchParams.get('sort') || '',
      installedOnly: parsedUrl.searchParams.get('installed') === '1'
    });

    return sendJson(res, 200, {
      specs,
      genres: getAllGenres(),
      installedCount: installedList.length,
      games: filteredGames
    });
  }

  // API: Get locally installed PC games + their compatibility analysis
  if (pathname === '/api/installed' && req.method === 'GET') {
    const refresh = parsedUrl.searchParams.get('refresh') === '1';
    const optimizationMode = parsedUrl.searchParams.get('mode') || 'optimal';
    const specs = getSpecs(refresh);
    const installedRaw = getInstalled(refresh);
    const games = installedRaw.map((game) => ({
      ...game,
      analysis: analyzeGameCompatibility(specs, game, {
        optimizationMode,
        targetDisplay: specs.display
      })
    }));

    return sendJson(res, 200, {
      specs,
      count: games.length,
      installedGames: games,
      games
    });
  }

  // API: Parse pasted raw Steam / PCGW requirements text and analyze compatibility
  if (pathname === '/api/parse-reqs' && req.method === 'POST') {
    try {
      const body = await parseBody(req);
      const rawText = body.text || body.rawText || body.requirementsText || '';
      if (!String(rawText).trim()) {
        return sendJson(res, 400, { error: 'Please paste system requirements text to parse.' });
      }

      const optimizationMode = body.optimizationMode || 'optimal';
      const customSpecs = resolveSpecsWithOverrides(getSpecs(), body.customHardware, body.targetDisplay);
      const analysisOptions = {
        optimizationMode,
        targetDisplay: customSpecs.display
      };

      const game = parseRawRequirementsText(rawText, {
        title: body.title || 'Custom Steam Game',
        genre: body.genre || 'Custom / Steam Spec'
      });

      const analysis = analyzeGameCompatibility(customSpecs, game, analysisOptions);
      const perSettingImpact = getPerSettingImpact(customSpecs, game, analysis, analysisOptions);
      const exportedConfigs = exportGameConfigFiles(customSpecs, game, analysis, analysisOptions);
      analysis.perSettingImpact = perSettingImpact;
      analysis.exportedConfigs = exportedConfigs;

      return sendJson(res, 200, {
        specs: customSpecs,
        game,
        analysis,
        perSettingImpact,
        exportedConfigs,
        optimizationMode
      });
    } catch (err) {
      return sendJson(res, 400, { error: err.message });
    }
  }

  // API: Analyze a specific game or custom hardware override ("What-If Upgrade Simulator" or Custom Game)
  if (pathname === '/api/analyze' && req.method === 'POST') {
    try {
      const body = await parseBody(req);
      const optimizationMode = body.optimizationMode || 'optimal';
      const customSpecs = resolveSpecsWithOverrides(getSpecs(), body.customHardware, body.targetDisplay);
      const analysisOptions = {
        optimizationMode,
        targetDisplay: customSpecs.display
      };

      let game = null;
      if (body.rawRequirementsText) {
        game = parseRawRequirementsText(body.rawRequirementsText, {
          title: body.title || (body.customGame && body.customGame.title) || 'Custom Steam Game',
          genre: body.genre || (body.customGame && body.customGame.genre) || 'Custom / Steam Spec'
        });
      } else if (body.customGame) {
        if (body.customGame.minimum && body.customGame.recommended) {
          game = enrichGameScores(body.customGame);
        } else {
          game = enrichGameScores({
            id: body.customGame.id || 'custom-game',
            title: body.customGame.title || 'Custom Game',
            genre: body.customGame.genre || 'Custom',
            releaseYear: body.customGame.releaseYear || 2025,
            engine: body.customGame.engine || 'Custom',
            supportsRT: Boolean(body.customGame.supportsRT),
            supportsUpscaling: body.customGame.supportsUpscaling || ['DLSS', 'FSR'],
            storageGB: Number(body.customGame.storageGB) || 60,
            ssdRequired: body.customGame.ssdRequired !== undefined ? Boolean(body.customGame.ssdRequired) : true,
            minimum: {
              cpu: body.customGame.minCpu || 'Intel Core i5-8400',
              gpu: body.customGame.minGpu || 'GTX 1060',
              ramGB: Number(body.customGame.minRamGB) || 8,
              vramGB: Number(body.customGame.minVramGB) || 4
            },
            recommended: {
              cpu: body.customGame.recCpu || 'AMD Ryzen 5 5600',
              gpu: body.customGame.recGpu || 'RTX 3060',
              ramGB: Number(body.customGame.recRamGB) || 16,
              vramGB: Number(body.customGame.recVramGB) || 8
            },
            tuningTips: body.customGame.tuningTips || [
              'Custom game analyzed using heuristic CPU/GPU benchmark scoring.',
              'Adjust Shadow Quality and Volumetric effects first if you need a quick +15-20% FPS boost.'
            ]
          });
        }
      } else {
        const targetId = body.gameId || 'cyberpunk-2077';
        const installedList = getInstalled();
        const instMatch = installedList.find((g) => g.id === targetId || g.matchedCatalogId === targetId) || null;
        game = getGameById(targetId);
        if (game && instMatch) {
          game = {
            ...game,
            installed: true,
            launcher: instMatch.launcher,
            drive: instMatch.drive,
            sizeOnDiskGB: instMatch.sizeOnDiskGB,
            installDir: instMatch.installDir,
            runtime: instMatch.runtime || null,
            protonVersion: instMatch.protonVersion || null,
            linuxCompatNote: instMatch.linuxCompatNote || null,
            isRunning: Boolean(instMatch.isRunning),
            wasRecentlyPlayed: Boolean(instMatch.wasRecentlyPlayed),
            playStatus: instMatch.playStatus || 'INSTALLED',
            playStatusLabel: instMatch.playStatusLabel || '💾 Installed',
            lastPlayedTimestamp: instMatch.lastPlayedTimestamp || 0
          };
        } else if (!game) {
          game = instMatch;
        }
      }

      if (!game) {
        return sendJson(res, 404, { error: 'Game not found' });
      }

      const analysis = analyzeGameCompatibility(customSpecs, game, analysisOptions);
      const perSettingImpact = getPerSettingImpact(customSpecs, game, analysis, analysisOptions);
      const exportedConfigs = exportGameConfigFiles(customSpecs, game, analysis, analysisOptions);
      analysis.perSettingImpact = perSettingImpact;
      analysis.exportedConfigs = exportedConfigs;

      return sendJson(res, 200, {
        specs: customSpecs,
        game,
        analysis,
        perSettingImpact,
        exportedConfigs,
        optimizationMode
      });
    } catch (err) {
      return sendJson(res, 400, { error: err.message });
    }
  }

  // API: Patch Status / Apply / Create / Rollback
  if (pathname === '/api/patch-status' && req.method === 'GET') {
    return sendJson(res, 200, getPatchStatus());
  }
  if (pathname === '/api/apply-patch' && req.method === 'POST') {
    try {
      const body = await parseBody(req);
      const result = await applyPatch(body);
      return sendJson(res, 200, result);
    } catch (err) {
      return sendJson(res, 400, { error: err.message });
    }
  }
  if (pathname === '/api/create-patch' && req.method === 'POST') {
    try {
      const body = await parseBody(req);
      const result = await createPatch(body);
      return sendJson(res, 200, result);
    } catch (err) {
      return sendJson(res, 400, { error: err.message });
    }
  }
  if (pathname === '/api/rollback-patch' && req.method === 'POST') {
    try {
      const body = await parseBody(req);
      const result = await rollbackPatch(body);
      return sendJson(res, 200, result);
    } catch (err) {
      return sendJson(res, 400, { error: err.message });
    }
  }

  // API: Firewall Status & Outbound Network Permission + Verified Component Price & Deals Finder
  if (pathname === '/api/firewall-status' && req.method === 'GET') {
    return sendJson(res, 200, getFirewallStatus());
  }
  if (pathname === '/api/firewall-access' && req.method === 'POST') {
    try {
      const body = await parseBody(req);
      if (body && body.revoke === true) {
        return sendJson(res, 200, revokeFirewallAccess());
      }
      const result = await requestFirewallAccess({ ...body, autoApprove: true });
      return sendJson(res, 200, result);
    } catch (err) {
      return sendJson(res, 400, { error: err.message });
    }
  }
  if (pathname === '/api/deals' && (req.method === 'POST' || req.method === 'GET')) {
    try {
      const body = req.method === 'POST'
        ? await parseBody(req)
        : {
            query: parsedUrl.searchParams.get('q') || parsedUrl.searchParams.get('query') || 'AMD Radeon RX 7600',
            country: parsedUrl.searchParams.get('country') || 'AR',
            strictReputation: parsedUrl.searchParams.get('strict') !== '0'
          };
      const result = await searchComponentDeals(body);
      return sendJson(res, 200, result);
    } catch (err) {
      return sendJson(res, 400, { error: err.message });
    }
  }

  // Static file server
  const filePath = path.join(PUBLIC_DIR, pathname === '/' ? 'index.html' : pathname);
  if (!filePath.startsWith(PUBLIC_DIR)) {
    res.writeHead(403);
    return res.end('Forbidden');
  }

  fs.readFile(filePath, (err, content) => {
    if (err) {
      res.writeHead(404);
      return res.end('Not found');
    }
    const ext = path.extname(filePath);
    res.writeHead(200, { 'Content-Type': MIME_TYPES[ext] || 'text/plain' });
    res.end(content);
  });
});

if (require.main === module) {
  server.listen(PORT, () => {
    console.log(`PC Game Checker running at http://localhost:${PORT}`);
  });
}

module.exports = { server, resolveSpecsWithOverrides };

const { enrichGameScores } = require('./games-db');
const { scoreCPU, scoreGPU } = require('./hardware');

/**
 * Extracts VRAM in GB from a GPU string or dedicated VRAM line.
 */
function extractVramFromText(gpuLine = '', sectionText = '') {
  // Check explicit VRAM line first: e.g. "VRAM: 8 GB" or "Video Memory: 6144 MB"
  const explicitVram = sectionText.match(/(?:vram|video\s*memory|dedicated\s*video\s*ram)\s*[:=-]?\s*(\d+(?:\.\d+)?)\s*(gb|mb)/i);
  if (explicitVram) {
    const val = parseFloat(explicitVram[1]);
    return explicitVram[2].toLowerCase() === 'mb' ? Math.max(1, Math.round(val / 1024)) : Math.round(val);
  }

  // Check inside the GPU string: e.g. "GTX 1060 6GB" or "RTX 3070 (8 GB)"
  const inlineGb = gpuLine.match(/(\d+)\s*gb\b/i);
  if (inlineGb) {
    return parseInt(inlineGb[1], 10);
  }
  const inlineMb = gpuLine.match(/(\d{4,5})\s*mb\b/i);
  if (inlineMb) {
    return Math.max(1, Math.round(parseInt(inlineMb[1], 10) / 1024));
  }

  // Fallback to hardware benchmark table default VRAM for that GPU
  const gpuEval = scoreGPU(gpuLine, null);
  return gpuEval.vramGB || 6;
}

/**
 * Extracts RAM in GB from a section of requirements text.
 */
function extractRamGB(sectionText = '', fallback = 16) {
  const ramLine = sectionText.match(/(?:memory|ram|memoria|system\s*ram)\s*[:=-]?\s*(\d+(?:\.\d+)?)\s*(gb|mb)/i)
    || sectionText.match(/\b(\d+)\s*gb\s*ram\b/i);
  if (ramLine) {
    const val = parseFloat(ramLine[1]);
    const unit = (ramLine[2] || 'gb').toLowerCase();
    return unit === 'mb' ? Math.max(2, Math.round(val / 1024)) : Math.round(val);
  }
  return fallback;
}

/**
 * Extracts Storage in GB from full requirements text.
 */
function extractStorageGB(fullText = '', fallback = 70) {
  const storageMatch = fullText.match(/(?:storage|hard\s*drive|disk\s*space|available\s*space|almacenamiento|hd\s*space)\s*[:=-]?\s*(\d+(?:\.\d+)?)\s*(tb|gb|mb)/i)
    || fullText.match(/\b(\d+(?:\.\d+)?)\s*(tb|gb)\s*(?:available\s*space|free\s*space|ssd|hdd|storage)/i);
  if (storageMatch) {
    const val = parseFloat(storageMatch[1]);
    const unit = storageMatch[2].toLowerCase();
    if (unit === 'tb') return Math.round(val * 1024);
    if (unit === 'mb') return Math.max(1, Math.round(val / 1024));
    return Math.round(val);
  }
  return fallback;
}

/**
 * Extracts CPU and GPU requirement strings from a section block.
 */
function extractCpuAndGpuFromBlock(blockText = '') {
  const lines = blockText
    .split(/\r?\n/)
    .map((l) => l.trim())
    .filter(Boolean);

  let cpu = '';
  let gpu = '';

  for (const line of lines) {
    if (!cpu && /^(?:processor|cpu|procesador)\s*[:=-]\s*(.+)/i.test(line)) {
      cpu = line.replace(/^(?:processor|cpu|procesador)\s*[:=-]\s*/i, '').trim();
      continue;
    }
    if (!gpu && /^(?:graphics|video\s*card|gpu|tarjeta\s*gr[aá]fica|video)\s*[:=-]\s*(.+)/i.test(line)) {
      gpu = line.replace(/^(?:graphics|video\s*card|gpu|tarjeta\s*gr[aá]fica|video)\s*[:=-]\s*/i, '').trim();
      continue;
    }
  }

  // Fallback heuristic scan if user pasted unlabeled lines (e.g. "Intel Core i7-9700 / Ryzen 5 5500")
  if (!cpu) {
    const cpuCandidate = lines.find((l) => /(?:intel\s*core|i[3579]-\d{3,5}|ryzen\s*[3579]|fx-\d{4}|phenom|pentium|athlon)/i.test(l)
      && !/(?:geforce|radeon|gtx|rtx|rx\s*\d{3,4}|arc\s*a\d{3})/i.test(l));
    if (cpuCandidate) {
      cpu = cpuCandidate.replace(/^(?:processor|cpu)\s*[:=-]?\s*/i, '').trim();
    }
  }

  if (!gpu) {
    const gpuCandidate = lines.find((l) => /(?:geforce|radeon|nvidia|amd\s*rx|gtx\s*\d{3,4}|rtx\s*\d{3,4}|rx\s*\d{3,4}|arc\s*[ab]\d{3}|vega\s*\d+)/i.test(l));
    if (gpuCandidate) {
      gpu = gpuCandidate.replace(/^(?:graphics|gpu|video\s*card)\s*[:=-]?\s*/i, '').trim();
    }
  }

  return { cpu, gpu };
}

/**
 * Parses pasted Steam / PCGamingWiki system requirements text into a structured,
 * benchmark-scored game object ready for analyzeGameCompatibility().
 */
function parseRawRequirementsText(text = '', titleOrOptions = 'Custom Steam Game') {
  const raw = String(text || '').trim();
  const resolvedTitle = typeof titleOrOptions === 'object' && titleOrOptions !== null
    ? (titleOrOptions.title || 'Custom Steam Game')
    : (titleOrOptions || 'Custom Steam Game');
  const resolvedGenre = typeof titleOrOptions === 'object' && titleOrOptions !== null && titleOrOptions.genre
    ? titleOrOptions.genre
    : 'Custom / Steam Spec';

  // Split into Minimum and Recommended sections if headers exist
  const recSplitRegex = /(?:^|\n)\s*(?:recommended|recomendado|recommended\s*specifications?)\s*:?/i;
  const minHeaderRegex = /(?:^|\n)\s*(?:minimum|m[ií]nimo|minimum\s*specifications?)\s*:?/i;

  let minBlock = raw;
  let recBlock = '';

  const recMatch = raw.match(recSplitRegex);
  if (recMatch && typeof recMatch.index === 'number') {
    minBlock = raw.slice(0, recMatch.index).replace(minHeaderRegex, '').trim();
    recBlock = raw.slice(recMatch.index + recMatch[0].length).trim();
  } else {
    minBlock = raw.replace(minHeaderRegex, '').trim();
  }

  const minExtracted = extractCpuAndGpuFromBlock(minBlock);
  const recExtracted = recBlock ? extractCpuAndGpuFromBlock(recBlock) : { cpu: '', gpu: '' };

  const minCpu = minExtracted.cpu || 'Intel Core i5-8400 or AMD Ryzen 5 1600';
  const minGpu = minExtracted.gpu || 'NVIDIA GeForce GTX 1060 6GB or AMD Radeon RX 580 8GB';
  const minRamGB = extractRamGB(minBlock, 8);
  const minVramGB = extractVramFromText(minGpu, minBlock || raw);

  // If Recommended block wasn't explicitly provided, derive sensible Recommended specs
  let recCpu = recExtracted.cpu;
  let recGpu = recExtracted.gpu;
  if (!recCpu) {
    const minCpuScore = scoreCPU(minCpu).score;
    recCpu = minCpuScore >= 65
      ? minCpu
      : 'Intel Core i7-10700 or AMD Ryzen 5 5600';
  }
  if (!recGpu) {
    const minGpuScore = scoreGPU(minGpu, minVramGB).score;
    recGpu = minGpuScore >= 60
      ? minGpu
      : 'NVIDIA GeForce RTX 3060 or AMD Radeon RX 6600 XT';
  }

  const recRamGB = recBlock
    ? extractRamGB(recBlock, Math.max(16, minRamGB))
    : Math.max(16, minRamGB);
  const recVramGB = recBlock
    ? extractVramFromText(recGpu, recBlock)
    : Math.max(8, minVramGB);

  const storageGB = extractStorageGB(raw, 70);
  const ssdRequired = /ssd|nvme|solid\s*state/i.test(raw) || storageGB >= 70;
  const supportsRT = /ray\s*tracing|path\s*tracing|\brtx\b|\bdxr\b/i.test(raw);

  const upscalers = [];
  if (/dlss|rtx/i.test(raw)) upscalers.push('DLSS');
  if (/fsr|radeon|fidelityfx/i.test(raw)) upscalers.push('FSR');
  if (/xess|arc\s*[ab]\d{3}/i.test(raw)) upscalers.push('XeSS');
  if (upscalers.length === 0) upscalers.push('DLSS', 'FSR');

  const slugId = String(resolvedTitle)
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '') || 'custom-steam-game';

  const tuningTips = [
    `Parsed directly from Steam/PCGW requirements (${minGpu} min -> ${recGpu} rec).`,
    recVramGB >= 8
      ? `Keep Texture Quality at High on 8GB VRAM GPUs and lower Shadow/Volumetric settings first for a +18% FPS boost.`
      : `Modest VRAM footprint (${recVramGB} GB recommended)—most modern GPUs can use High/Ultra textures safely.`,
    ssdRequired
      ? 'Install on an NVMe/SATA SSD to eliminate asset streaming stutter.'
      : 'Enable DLSS/FSR Quality mode if you need extra headroom at 1440p.'
  ];

  return enrichGameScores({
    id: slugId,
    title: resolvedTitle,
    genre: resolvedGenre,
    releaseYear: new Date().getFullYear(),
    engine: /unreal\s*engine\s*5|\bue5\b/i.test(raw) ? 'Unreal Engine 5' : 'Steam Spec Lookup',
    supportsRT,
    supportsUpscaling: upscalers,
    storageGB,
    ssdRequired,
    baseRecFps: 64,
    parsedFromRawText: true,
    minimum: {
      cpu: minCpu,
      gpu: minGpu,
      ramGB: minRamGB,
      vramGB: minVramGB
    },
    recommended: {
      cpu: recCpu,
      gpu: recGpu,
      ramGB: recRamGB,
      vramGB: recVramGB
    },
    tuningTips
  });
}

const TIER_WEIGHT = {
  EXCEEDS_RECOMMENDED: 4,
  MEETS_RECOMMENDED: 3,
  MEETS_MINIMUM: 2,
  BELOW_MINIMUM: 1
};

/**
 * Filters and sorts an array of games (optionally enriched with `.analysis` and `.installed`).
 */
function filterAndSortGames(games = [], { query = '', genre = '', tier = '', sortBy = '', installedOnly = false } = {}) {
  if (!Array.isArray(games)) return [];

  const q = String(query || '').trim().toLowerCase();
  const gFilter = String(genre || '').trim().toLowerCase();
  const tFilter = String(tier || '').trim().toUpperCase();
  const sortKey = String(sortBy || '').trim().toLowerCase();

  const filtered = games.filter((game) => {
    if (!game) return false;

    if (installedOnly && !(game.installed || game.isInstalled)) {
      return false;
    }

    if (q) {
      const hay = `${game.title || ''} ${game.genre || ''} ${game.engine || ''} ${game.id || ''}`.toLowerCase();
      if (!hay.includes(q)) return false;
    }

    if (gFilter && gFilter !== 'all') {
      const gameGenre = String(game.genre || '').toLowerCase();
      if (!gameGenre.includes(gFilter)) return false;
    }

    if (tFilter && tFilter !== 'ALL') {
      const gameTier = game.analysis?.overallTier || '';
      if (tFilter === 'PLAYABLE') {
        if (!game.analysis?.canRunMinimum) return false;
      } else if (tFilter === 'RECOMMENDED') {
        if (!game.analysis?.canRunRecommended) return false;
      } else if (gameTier && gameTier !== tFilter) {
        return false;
      }
    }

    return true;
  });

  const sorted = [...filtered];
  sorted.sort((a, b) => {
    if (sortKey === 'fps' || sortKey === 'fps-desc') {
      const fpsA = a.analysis?.optimalConfig?.estimatedFps?.['1080p']?.avg ?? a.baseRecFps ?? 0;
      const fpsB = b.analysis?.optimalConfig?.estimatedFps?.['1080p']?.avg ?? b.baseRecFps ?? 0;
      return fpsB - fpsA;
    }
    if (sortKey === 'fps-asc') {
      const fpsA = a.analysis?.optimalConfig?.estimatedFps?.['1080p']?.avg ?? a.baseRecFps ?? 0;
      const fpsB = b.analysis?.optimalConfig?.estimatedFps?.['1080p']?.avg ?? b.baseRecFps ?? 0;
      return fpsA - fpsB;
    }
    if (sortKey === 'title' || sortKey === 'name') {
      return String(a.title || '').localeCompare(String(b.title || ''));
    }
    if (sortKey === 'year' || sortKey === 'releaseyear' || sortKey === 'newest') {
      return (b.releaseYear || 0) - (a.releaseYear || 0);
    }
    if (sortKey === 'storage' || sortKey === 'size') {
      return (b.storageGB || 0) - (a.storageGB || 0);
    }
    if (sortKey === 'demanding' || sortKey === 'gpuscore') {
      return (b.recommended?.gpuScore || 0) - (a.recommended?.gpuScore || 0);
    }
    if (sortKey === 'tier' || sortKey === 'compatibility') {
      const rankA = TIER_WEIGHT[a.analysis?.overallTier] || 0;
      const rankB = TIER_WEIGHT[b.analysis?.overallTier] || 0;
      if (rankB !== rankA) return rankB - rankA;
      const fpsA = a.analysis?.optimalConfig?.estimatedFps?.['1080p']?.avg ?? 0;
      const fpsB = b.analysis?.optimalConfig?.estimatedFps?.['1080p']?.avg ?? 0;
      return fpsB - fpsA;
    }
    if (!sortKey || sortKey === 'default' || sortKey === 'activity') {
      const getActivityRank = (g) => {
        if (g.isRunning || g.playStatus === 'PLAYING_NOW') return 3;
        if (g.wasRecentlyPlayed || g.playStatus === 'RECENTLY_PLAYED') return 2;
        if (g.installed || g.isInstalled || g.playStatus === 'INSTALLED') return 1;
        return 0;
      };
      const actDiff = getActivityRank(b) - getActivityRank(a);
      if (actDiff !== 0) return actDiff;
      if ((b.lastPlayedTimestamp || 0) !== (a.lastPlayedTimestamp || 0)) {
        return (b.lastPlayedTimestamp || 0) - (a.lastPlayedTimestamp || 0);
      }
    }
    return 0;
  });

  return sorted;
}

module.exports = {
  parseRawRequirementsText,
  filterAndSortGames
};

const fs = require('fs');
const path = require('path');

const DEFAULT_ROOT = path.join(__dirname, '..');

/**
 * Parses a CalVer string (`YYYY.MM.DD`, `YYYY.MM.DD.PATCH`, `YYYY.MM.DD-PATCH`, `vYYYY.MM.DD`)
 */
function parseCalVer(str) {
  if (!str || typeof str !== 'string') {
    return { valid: false };
  }
  const cleaned = str.trim().replace(/^v/i, '');
  const match = cleaned.match(/^(\d{4})[.-](\d{1,2})[.-](\d{1,2})(?:[.-](\d+))?$/);
  if (!match) {
    return { valid: false };
  }

  const year = parseInt(match[1], 10);
  const month = parseInt(match[2], 10);
  const day = parseInt(match[3], 10);
  const patchLevel = match[4] !== undefined ? parseInt(match[4], 10) : 0;

  if (year < 2000 || year > 2100 || month < 1 || month > 12 || day < 1 || day > 31 || patchLevel < 0) {
    return { valid: false };
  }

  const mm = String(month).padStart(2, '0');
  const dd = String(day).padStart(2, '0');
  const calver = `${year}.${mm}.${dd}`;
  const fullVersion = patchLevel > 0 ? `${calver}.${patchLevel}` : calver;
  const npmVersion = patchLevel > 0 ? `${calver}-${patchLevel}` : calver;

  return {
    valid: true,
    year,
    month,
    day,
    patchLevel,
    calver,
    fullVersion,
    npmVersion
  };
}

/**
 * Formats a Date object or date string into a CalVer string `YYYY.MM.DD` or `YYYY.MM.DD.PATCH`
 */
function formatCalVer(dateInput = new Date(), patchLevel = 0) {
  let year;
  let month;
  let day;

  if (typeof dateInput === 'string') {
    const parsed = parseCalVer(dateInput);
    if (parsed.valid) {
      year = parsed.year;
      month = parsed.month;
      day = parsed.day;
      if (patchLevel === 0 && parsed.patchLevel > 0) {
        patchLevel = parsed.patchLevel;
      }
    } else {
      const d = new Date(dateInput);
      year = d.getFullYear();
      month = d.getMonth() + 1;
      day = d.getDate();
    }
  } else if (dateInput instanceof Date) {
    year = dateInput.getFullYear();
    month = dateInput.getMonth() + 1;
    day = dateInput.getDate();
  } else {
    const d = new Date();
    year = d.getFullYear();
    month = d.getMonth() + 1;
    day = d.getDate();
  }

  const mm = String(month).padStart(2, '0');
  const dd = String(day).padStart(2, '0');
  const base = `${year}.${mm}.${dd}`;
  return patchLevel > 0 ? `${base}.${patchLevel}` : base;
}

/**
 * Compares two CalVer strings (`a` and `b`).
 * Returns -1 if a < b, 0 if a === b, 1 if a > b.
 */
function compareCalVer(a, b) {
  const pa = typeof a === 'object' && a !== null && a.valid ? a : parseCalVer(String(a || ''));
  const pb = typeof b === 'object' && b !== null && b.valid ? b : parseCalVer(String(b || ''));

  if (!pa.valid && !pb.valid) return 0;
  if (!pa.valid) return -1;
  if (!pb.valid) return 1;

  if (pa.year !== pb.year) return pa.year > pb.year ? 1 : -1;
  if (pa.month !== pb.month) return pa.month > pb.month ? 1 : -1;
  if (pa.day !== pb.day) return pa.day > pb.day ? 1 : -1;
  if (pa.patchLevel !== pb.patchLevel) return pa.patchLevel > pb.patchLevel ? 1 : -1;
  return 0;
}

/**
 * Reads the current CalVer metadata from `version.json`
 */
function getVersionInfo(appRootDir = DEFAULT_ROOT) {
  const versionFilePath = path.join(appRootDir, 'version.json');
  try {
    if (fs.existsSync(versionFilePath)) {
      const raw = JSON.parse(fs.readFileSync(versionFilePath, 'utf8'));
      const parsed = parseCalVer(raw.fullVersion || raw.calver || '2026.11.17');
      const patchLevel = typeof raw.patchLevel === 'number' ? raw.patchLevel : (parsed.patchLevel || 0);
      const calver = raw.calver || parsed.calver || '2026.11.17';
      const fullVersion = raw.fullVersion || (patchLevel > 0 ? `${calver}.${patchLevel}` : calver);
      const npmVersion = raw.npmVersion || (patchLevel > 0 ? `${calver}-${patchLevel}` : calver);
      const gitTag = raw.gitTag || `v${fullVersion}`;
      const history = Array.isArray(raw.history) ? raw.history : [];
      return {
        calver,
        npmVersion,
        patchLevel,
        fullVersion,
        gitTag,
        scheme: raw.scheme || 'YYYY.MM.DD[.PATCH]',
        channel: raw.channel || 'stable',
        releasedAt: raw.releasedAt || new Date().toISOString(),
        notes: raw.notes || `CalVer ${fullVersion} Release`,
        history
      };
    }
  } catch (e) {
    // fallback below
  }

  return {
    calver: '2026.11.17',
    npmVersion: '2026.11.17-1',
    patchLevel: 1,
    fullVersion: '2026.11.17.1',
    gitTag: 'v2026.11.17.1',
    scheme: 'YYYY.MM.DD[.PATCH]',
    channel: 'stable',
    releasedAt: new Date().toISOString(),
    notes: 'CalVer 2026.11.17.1 Native Desktop Release',
    history: []
  };
}

/**
 * Bumps or sets the CalVer version in `version.json` (and optionally `package.json`).
 */
function bumpCalVer(options = {}) {
  const {
    mode = 'date',
    targetCalVer = null,
    notes = null,
    customDate = null,
    channel = null,
    appRootDir = DEFAULT_ROOT,
    updatePackageJson = true
  } = options;

  const current = getVersionInfo(appRootDir);
  let nextCalver = current.calver;
  let nextPatch = current.patchLevel || 0;

  if (mode === 'set' || targetCalVer) {
    const parsed = parseCalVer(targetCalVer || customDate || '');
    if (!parsed.valid) {
      throw new Error(`Invalid CalVer string: "${targetCalVer || customDate}"`);
    }
    nextCalver = parsed.calver;
    nextPatch = parsed.patchLevel;
  } else if (mode === 'patch' || mode === 'bump-patch') {
    nextPatch = (current.patchLevel || 0) + 1;
  } else {
    // mode === 'date' / 'bump'
    const candidateDate = formatCalVer(customDate || new Date(), 0);
    if (candidateDate === current.calver) {
      nextPatch = (current.patchLevel || 0) + 1;
    } else {
      nextCalver = candidateDate;
      nextPatch = 0;
    }
  }

  const fullVersion = nextPatch > 0 ? `${nextCalver}.${nextPatch}` : nextCalver;
  const npmVersion = nextPatch > 0 ? `${nextCalver}-${nextPatch}` : nextCalver;
  const gitTag = `v${fullVersion}`;
  const releasedAt = new Date().toISOString();
  const resolvedNotes = notes || `CalVer ${fullVersion} update`;

  const prevHistory = Array.isArray(current.history) ? current.history.slice() : [];
  const newHistoryEntry = {
    version: fullVersion,
    calver: nextCalver,
    patchLevel: nextPatch,
    gitTag,
    releasedAt,
    notes: resolvedNotes
  };
  const updatedHistory = [
    newHistoryEntry,
    ...prevHistory.filter((h) => h && h.version !== fullVersion)
  ];

  const updated = {
    calver: nextCalver,
    npmVersion,
    patchLevel: nextPatch,
    fullVersion,
    gitTag,
    scheme: 'YYYY.MM.DD[.PATCH]',
    channel: channel || current.channel || 'stable',
    releasedAt,
    notes: resolvedNotes,
    history: updatedHistory
  };

  const versionFilePath = path.join(appRootDir, 'version.json');
  fs.writeFileSync(versionFilePath, JSON.stringify(updated, null, 2) + '\n', 'utf8');

  if (updatePackageJson) {
    const pkgPath = path.join(appRootDir, 'package.json');
    if (fs.existsSync(pkgPath)) {
      try {
        const pkg = JSON.parse(fs.readFileSync(pkgPath, 'utf8'));
        pkg.version = npmVersion;
        fs.writeFileSync(pkgPath, JSON.stringify(pkg, null, 2) + '\n', 'utf8');
      } catch (e) {
        // ignore package.json write errors if locked
      }
    }
  }

  return updated;
}

module.exports = {
  getVersionInfo,
  formatCalVer,
  parseCalVer,
  compareCalVer,
  bumpCalVer
};

